func TestEnumAgentSkillSearchRequestMarkdownFormat(t *testing.T) {
	t.Run("NewFromString_agent", func(t *testing.T) {
		t.Parallel()
		val, err := NewAgentSkillSearchRequestMarkdownFormatFromString("agent")
		assert.NoError(t, err, "valid enum value should not return error")
		assert.Equal(t, AgentSkillSearchRequestMarkdownFormat("agent"), val, "enum value should match expected wire value")
	})

	t.Run("NewFromString_full", func(t *testing.T) {
		t.Parallel()
		val, err := NewAgentSkillSearchRequestMarkdownFormatFromString("full")
		assert.NoError(t, err, "valid enum value should not return error")
		assert.Equal(t, AgentSkillSearchRequestMarkdownFormat("full"), val, "enum value should match expected wire value")
	})

	t.Run("NewFromString_Invalid", func(t *testing.T) {
		_, err := NewAgentSkillSearchRequestMarkdownFormatFromString("invalid_value_that_does_not_exist")
		assert.Error(t, err)
	})

	t.Run("Ptr", func(t *testing.T) {
		val, err := NewAgentSkillSearchRequestMarkdownFormatFromString("agent")
		assert.NoError(t, err)
		ptr := val.Ptr()
		assert.NotNil(t, ptr)
		assert.Equal(t, val, *ptr)
	})
}
